Rules.InvariantScript:
Set(
    currentLifeguard,
    LookUp(LifeguardDetails, Email = User().Email)
);
Set(
    lifeguardBeaches,
    Split(currentLifeguard.'Selected Beaches', ",")
);
Set(selectedBeach, "");
Set(selectedShift, "")

ForAll(
    Sequence(
        DateDiff(
            TimeValue(varSelectedBeach.Opens),
            TimeValue(varSelectedBeach.Closes),
            TimeUnit.Hours
        ) / 2
    ),
    {
        Slot:
        Text(
            DateAdd(
                TimeValue(varSelectedBeach.Opens),
                (Value - 1) * 2,
                TimeUnit.Hours
            ), "HH:mm"
        )
        & " - " &
        Text(
            DateAdd(
                TimeValue(varSelectedBeach.Opens),
                Value * 2,
                TimeUnit.Hours
            ), "HH:mm"
        )
    }
)

If(
    IsBlank(Dropdown1.Selected.Value) Or IsBlank(Dropdown2.Selected.Slot),
    Notify("Please select a beach and time slot", NotificationType.Error),
    Patch(
        LifeguardDetails,
        LookUp(LifeguardDetails, ID = varVolunteer.ID),
        {
            'Beach Today': Trim(Dropdown1.Selected.Value),
            SlotToday: Trim(Dropdown2.Selected.Slot)
        }
    );
    Set(varVolunteer, LookUp(LifeguardDetails, Email = varVolunteer.Email));
    Notify("Your beach and time slot have been saved!", NotificationType.Success);
    Navigate('Volunteer-Page 3')
)
